command:
sudo systemctl enable chronyd
echo BASELINE_BOOT_ID:
cat /proc/sys/kernel/random/boot_id
echo BASELINE_UPTIME:
uptime -s
echo CHRONY_TRACKING:
sudo chronyc tracking
echo CHRONY_SOURCES:
sudo chronyc sources
echo NTP_PORT_LISTEN:
sudo netstat -lnup 2>/dev/null | grep 123 || sudo ss -lnup 2>/dev/null | grep 123 || cat /proc/net/udp | grep -i 007b

